            possible_0 = False
        if val_n == 0 and val_kn == 0:
            possible_1 = False
    return possible_0, possible_1

def build_sequence_greedy(max_k):
    # Let's try to make y_k non-constant for as long as possible.
    y = [0] * (max_k + 1)
    # For k < 1088, we can set y_k = k % 2.
    for k in range(1088):
        y[k] = k % 2

    for k in range(1088, max_k + 1):
        p0, p1 = is_possible(k, y, 32, 1024)
        if p0 and p1:
            y[k] = 1 - y[k-1]
        elif p0:
            y[k] = 0
        elif p1:
            y[k] = 1
        else:
            return y, k
    return y, None

